// Real Win32/NT file objects; protected ACL and VM state are explicit adapters.
public static class MuOwnedStagingFixture {
    [DllImport("kernel32.dll",CharSet=CharSet.Unicode,SetLastError=true)]private static extern bool CreateHardLink(string created,string original,IntPtr security);
    [DllImport("kernel32.dll",CharSet=CharSet.Unicode,SetLastError=true)]private static extern Microsoft.Win32.SafeHandles.SafeFileHandle CreateFile(string path,uint access,uint share,IntPtr security,uint creation,uint flags,IntPtr template);
    private static string DataStream(string path,string value=null){using(var handle=CreateFile(path,value==null?0x80000000U:0xc0000000U,3,IntPtr.Zero,value==null?3U:2U,0x80,IntPtr.Zero)){if(handle.IsInvalid)throw new IOException("Fixture data stream failed ("+Marshal.GetLastWin32Error()+")");using(var file=new FileStream(handle,value==null?FileAccess.Read:FileAccess.ReadWrite)){if(value!=null){var bytes=Encoding.UTF8.GetBytes(value);file.Write(bytes,0,bytes.Length);file.Flush(true);file.Position=0;}using(var reader=new StreamReader(file))return reader.ReadToEnd();}}}
    private static void Require(bool value,string message){if(!value)throw new InvalidOperationException(message);}
    public static string Initial(string root){
        string id=Guid.NewGuid().ToString("D"),allocation=Path.Combine(root,id);Directory.CreateDirectory(allocation);System.IO.File.WriteAllBytes(Path.Combine(allocation,"disk.vhdx"),new byte[2097171]);System.IO.File.WriteAllBytes(Path.Combine(allocation,"seed.iso"),new byte[65536]);
        Action<string,bool> authority=(path,directory)=>{var attributes=System.IO.File.GetAttributes(path);Require((attributes&FileAttributes.ReparsePoint)==0&&((attributes&FileAttributes.Directory)!=0)==directory,"Ordinary fixture entry changed");};
        string stopAt=null;var factory=new MuSnapshotStaging(allocation,id,new string('a',64),authority);
        Func<MuOfflineSnapshotStore> store=()=>new MuOfflineSnapshotStore(allocation,id,p=>Directory.CreateDirectory(p),p=>new FileStream(p,FileMode.Open,FileAccess.Read,FileShare.Read),n=>{},()=>{},point=>{if(point==stopAt)throw new OperationCanceledException("Synthetic copy interruption");},factory);
        var saved=store().Create("完整新副本","opaque-owner-encrypted",CancellationToken.None);
        Require(Directory.Exists(Path.Combine(allocation,"snapshots",saved.id)),"Published directory was deleted on handle close");Require(store().Get(saved.id).id==saved.id,"Published snapshot unreadable");
        Require(System.IO.File.Exists(Path.Combine(allocation,"snapshots","staging-published-"+saved.id+".frames")),"Published producer receipt was not retained");
        var restored=store().PrepareRestore(saved.id,"opaque-current-encrypted",CancellationToken.None);Require(restored.phase=="applied","Owned restore was not applied");store().RecoverRestore(restored.id);store().AcknowledgeRestore(restored.id);
        stopAt="copy-disk";try{store().Create("中断新副本","opaque-owner-encrypted",CancellationToken.None);throw new InvalidOperationException("Missing interruption");}catch(OperationCanceledException){}
        var staging=store().Staging();Require(staging.entries.Length==1,"Interrupted original copy missing");string next=Path.Combine(allocation,"snapshots",staging.entries[0].name);Require(System.IO.File.Exists(Path.Combine(next,"disk.vhdx")),"Registered copy removed instead of retained");
        return new JavaScriptSerializer().Serialize(new{complete=true,realNtCreate=true,realHandleRename=true,deleteOnCloseCancelledAfterReceipt=true,producerReceipts=Directory.GetFiles(Path.Combine(allocation,"snapshots"),"staging-*.frames").Length,publishedCreate=true,publishedRestore=true,interruptedCopyRetained=true,actualHyperV=false,protectedAcl=false});
    }
    private sealed class Case {
        public string allocation,id,root,point,producerPoint;public MuSnapshotStaging factory;public string copyId,operation;public Action<string> observe;
        public Case(string directory):this(directory,null){}
        public Case(string directory,string existing){root=directory;id=existing??Guid.NewGuid().ToString("D");allocation=Path.Combine(root,id);if(existing==null){Directory.CreateDirectory(allocation);System.IO.File.WriteAllBytes(Path.Combine(allocation,"disk.vhdx"),Enumerable.Repeat((byte)71,2097171).ToArray());System.IO.File.WriteAllBytes(Path.Combine(allocation,"seed.iso"),Enumerable.Repeat((byte)72,65536).ToArray());}factory=Factory(new string('a',64));}
        public MuSnapshotStaging Factory(string authority){return new MuSnapshotStaging(allocation,id,authority,(path,directory)=>{var attributes=System.IO.File.GetAttributes(path);Require((attributes&FileAttributes.ReparsePoint)==0&&((attributes&FileAttributes.Directory)!=0)==directory,"Fixture path changed");},p=>{if(observe!=null)observe(p);if(p==producerPoint)throw new OperationCanceledException("Synthetic producer/deletion interruption");});}
        public MuOfflineSnapshotStore Store(){return new MuOfflineSnapshotStore(allocation,id,p=>Directory.CreateDirectory(p),p=>new FileStream(p,FileMode.Open,FileAccess.Read,FileShare.Read),n=>{},()=>{},p=>{if(observe!=null)observe(p);if(p==point)throw new OperationCanceledException("Synthetic core interruption");},factory);}
        public string Folder {get{return Path.Combine(allocation,"snapshots",operation+"-next-"+copyId);}}
        public void Prepare(string kind,string boundary){operation=kind;if(kind=="restore"){var saved=Store().Create("baseline","opaque-saved",CancellationToken.None);point=boundary;try{Store().PrepareRestore(saved.id,"opaque-current",CancellationToken.None);throw new InvalidOperationException("Missing boundary");}catch(OperationCanceledException){}}else{point=boundary;try{Store().Create("interrupted","opaque-saved",CancellationToken.None);throw new InvalidOperationException("Missing boundary");}catch(OperationCanceledException){}}point=null;copyId=Store().Staging().entries.Single().name.Substring((operation+"-next-").Length);}
        public string[] Current(){return new[]{"disk.vhdx","seed.iso"}.Select(name=>Hash(Path.Combine(allocation,name))).ToArray();}
        public Dictionary<string,string> Inventory(){return Directory.GetFiles(allocation,"*",SearchOption.AllDirectories).ToDictionary(file=>file.Substring(allocation.Length),file=>Hash(file));}
        public void Unchanged(Dictionary<string,string> before){var after=Inventory();Require(before.Count==after.Count&&before.All(entry=>after.ContainsKey(entry.Key)&&after[entry.Key]==entry.Value),"Refused cleanup changed original files");}
        public MuSnapshotStaging.Review Review(){return factory.Inspect(copyId,operation,CancellationToken.None);}
        public void Clean(bool resume=false){var review=Review();var before=Current();var result=factory.Cleanup(copyId,operation,review.token,resume,()=>{},CancellationToken.None);Require(result.deleted&&result.id==copyId&&result.operation==operation,"Cleanup receipt changed");Require(Current().SequenceEqual(before),"Cleanup touched current disk or seed");Require(!Directory.Exists(Folder)&&Store().Staging().entries.Length==0,"Cleanup did not settle staging inventory");}
    }
    private static string Hash(string file){using(var digest=SHA256.Create())using(var stream=System.IO.File.OpenRead(file))return Convert.ToBase64String(digest.ComputeHash(stream));}
    private static bool Fails(Action work){try{work();return false;}catch(IOException){return true;}catch(InvalidDataException){return true;}catch(InvalidOperationException){return true;}}
    public static string Run(string root){var checks=new List<object>();int number=0;Action<string,Action<Case>> test=(name,work)=>{var c=new Case(Path.Combine(root,(++number).ToString()));try{work(c);}catch(Exception error){throw new InvalidOperationException(name+": "+error.Message,error);}checks.Add(new{name=name,passed=true});};
        foreach(string kind in new[]{"create","restore"})foreach(string point in new[]{"copy-disk","copy-seed",kind=="create"?"create-before-publish":"restore-before-publish"})test(kind+"-original-copy-cleanup-"+point,c=>{c.Prepare(kind,point);var review=c.Review();Require(review.phase=="copy"&&review.files>=1&&review.files<=3&&review.bytes>0&&!review.partialReceipt,"Review facts changed");c.Clean();var settled=c.Review();Require(settled.phase=="done"&&settled.bytes==0,"Completion not durable");var again=c.factory.Cleanup(c.copyId,c.operation,settled.token,true,()=>{},CancellationToken.None);Require(again.deleted&&again.alreadyDeleted,"Completion retry not idempotent");c.Store().Create("retry-after-cleanup","opaque",CancellationToken.None);});
        foreach(string boundary in new[]{"staging-delete-planned","staging-delete-registered","staging-deleted-disk.vhdx","staging-deleted-seed.iso","staging-deleted-manifest.json","staging-directory-removed","staging-delete-done-durable"})test("resume-after-"+boundary,c=>{c.Prepare("create","create-before-publish");var review=c.Review();c.producerPoint=boundary;try{c.factory.Cleanup(c.copyId,c.operation,review.token,false,()=>{},CancellationToken.None);throw new InvalidOperationException("Missing cleanup interruption");}catch(OperationCanceledException){}c.producerPoint=null;Require(c.Store().Staging().entries.Any(entry=>entry.name=="create-next-"+c.copyId),"Incomplete cleanup disappeared from catalog");Require(c.Review().phase==(boundary=="staging-delete-done-durable"?"done":"deleting"),"Lost durable deletion plan");c.Clean(true);});
        test("unknown-receipt-does-not-adopt-legacy-prefix",c=>{c.operation="create";c.copyId=Guid.NewGuid().ToString("D");Directory.CreateDirectory(c.Folder);System.IO.File.WriteAllText(Path.Combine(c.Folder,"disk.vhdx"),"LEGACY_DATA");var before=c.Inventory();Require(Fails(()=>c.Review()),"Legacy tree adopted");c.Unchanged(before);});
        test("wrong-owner-authority-retains-all-originals",c=>{c.Prepare("create","copy-seed");var before=c.Inventory();Require(Fails(()=>c.Factory(new string('b',64)).Inspect(c.copyId,c.operation,CancellationToken.None)),"Another owner authority adopted files");c.Unchanged(before);});
        test("same-content-replacement-is-not-original-object",c=>{c.Prepare("create","copy-seed");string file=Path.Combine(c.Folder,"seed.iso");byte[] bytes=System.IO.File.ReadAllBytes(file);System.IO.File.Move(file,file+".original");System.IO.File.WriteAllBytes(file,bytes);System.IO.File.Delete(file+".original");var before=c.Inventory();Require(Fails(()=>c.Review()),"Replacement object adopted");c.Unchanged(before);});
        test("extra-file-retains-complete-unknown-tree",c=>{c.Prepare("create","copy-seed");System.IO.File.WriteAllText(Path.Combine(c.Folder,"unknown.txt"),"KEEP");var before=c.Inventory();Require(Fails(()=>c.Review()),"Extra file adopted");c.Unchanged(before);});
        test("nested-directory-is-not-traversed-or-removed",c=>{c.Prepare("create","copy-seed");Directory.CreateDirectory(Path.Combine(c.Folder,"nested"));System.IO.File.WriteAllText(Path.Combine(c.Folder,"nested","keep.txt"),"KEEP");var before=c.Inventory();Require(Fails(()=>c.Review()),"Nested tree adopted");c.Unchanged(before);});
        test("directory-replacement-does-not-follow-original-name",c=>{c.Prepare("create","copy-seed");Directory.Move(c.Folder,c.Folder+"-original");Directory.CreateDirectory(c.Folder);System.IO.File.WriteAllText(Path.Combine(c.Folder,"disk.vhdx"),"KEEP");var before=c.Inventory();Require(Fails(()=>c.Review()),"Directory replacement adopted");c.Unchanged(before);});
        test("stale-review-rejects-new-length-before-any-delete",c=>{c.Prepare("create","copy-seed");var review=c.Review();using(var file=new FileStream(Path.Combine(c.Folder,"seed.iso"),FileMode.Append,FileAccess.Write))file.WriteByte(3);var before=c.Inventory();Require(Fails(()=>c.factory.Cleanup(c.copyId,c.operation,review.token,false,()=>{},CancellationToken.None)),"Stale review deleted data");c.Unchanged(before);});
        test("resume-only-cannot-start-a-fresh-delete",c=>{c.Prepare("create","copy-seed");var review=c.Review();var before=c.Inventory();Require(Fails(()=>c.factory.Cleanup(c.copyId,c.operation,review.token,true,()=>{},CancellationToken.None)),"Resume-only initiated deletion");c.Unchanged(before);});
        foreach(int tail in new[]{1,3,9})test("recover-incomplete-receipt-tail-"+tail,c=>{c.Prepare("create","copy-seed");string receipt=Path.Combine(c.allocation,"snapshots","staging-owned-"+c.copyId+".frames");using(var stream=new FileStream(receipt,FileMode.Append,FileAccess.Write)){byte[] bytes=new byte[tail];byte[] length=BitConverter.GetBytes(256);Buffer.BlockCopy(length,0,bytes,0,Math.Min(4,tail));stream.Write(bytes,0,bytes.Length);stream.Flush(true);}Require(c.Review().partialReceipt,"Interrupted frame tail not identified");c.Clean();});
        test("complete-frame-corruption-is-not-truncated-away",c=>{c.Prepare("create","copy-seed");string receipt=Path.Combine(c.allocation,"snapshots","staging-owned-"+c.copyId+".frames");using(var stream=new FileStream(receipt,FileMode.Open,FileAccess.ReadWrite)){stream.Position=stream.Length-1;int value=stream.ReadByte();stream.Position--;stream.WriteByte((byte)(value^1));stream.Flush(true);}var before=c.Inventory();Require(Fails(()=>c.Review()),"Corrupt complete frame accepted");c.Unchanged(before);});
        test("cancellation-before-plan-keeps-review-and-files-unchanged",c=>{c.Prepare("create","copy-seed");var review=c.Review();var before=c.Inventory();var cancel=new CancellationTokenSource();cancel.Cancel();try{c.factory.Cleanup(c.copyId,c.operation,review.token,false,()=>{},cancel.Token);throw new InvalidOperationException("Cancellation ignored");}catch(OperationCanceledException){}c.Unchanged(before);});
        test("late-unknown-file-prevents-the-first-disposition",c=>{c.Prepare("create","copy-seed");var review=c.Review();bool added=false;c.observe=p=>{if(p=="staging-delete-registered"){System.IO.File.WriteAllText(Path.Combine(c.Folder,"late.txt"),"KEEP");added=true;}};Require(Fails(()=>c.factory.Cleanup(c.copyId,c.operation,review.token,false,()=>{},CancellationToken.None)),"Late unknown file ignored");Require(added&&System.IO.File.Exists(Path.Combine(c.Folder,"disk.vhdx"))&&System.IO.File.Exists(Path.Combine(c.Folder,"seed.iso"))&&System.IO.File.ReadAllText(Path.Combine(c.Folder,"late.txt"))=="KEEP","First original removed before full recheck");});
        test("hard-linked-original-copy-is-retained",c=>{c.Prepare("create","copy-seed");string file=Path.Combine(c.Folder,"disk.vhdx"),link=Path.Combine(c.root,"shared-copy.vhdx");Require(CreateHardLink(link,file,IntPtr.Zero),"Synthetic hard link creation failed");var before=c.Inventory();Require(Fails(()=>c.Review()),"Linked original was offered for deletion");c.Unchanged(before);Require(System.IO.File.Exists(link),"External original link changed");});
        test("alternate-data-stream-prevents-copy-deletion",c=>{c.Prepare("create","copy-seed");string stream=Path.Combine(c.Folder,"disk.vhdx")+":unregistered";DataStream(stream,"KEEP_STREAM");var before=c.Inventory();Require(Fails(()=>c.Review()),"Unknown data stream ignored");c.Unchanged(before);Require(DataStream(stream)=="KEEP_STREAM","Unknown stream removed");});
        test("published-restore-and-rollback-history-can-never-be-staging-cleaned",c=>{var saved=c.Store().Create("published","opaque",CancellationToken.None);var active=c.Store().PrepareRestore(saved.id,"opaque-current",CancellationToken.None);var before=c.Inventory();Require(Fails(()=>c.factory.Inspect(active.id,"restore",CancellationToken.None)),"Active rollback data offered for cleanup");c.Unchanged(before);c.Store().RecoverRestore(active.id);c.Store().AcknowledgeRestore(active.id);before=c.Inventory();Require(Fails(()=>c.factory.Inspect(active.id,"restore",CancellationToken.None)),"Acknowledged rollback history offered for staging cleanup");c.Unchanged(before);Require(c.Store().Get(saved.id).id==saved.id,"Published snapshot changed");});
        return new JavaScriptSerializer().Serialize(new{complete=true,realFileSystem=true,realNtCreate=true,realHandleDelete=true,actualHyperV=false,protectedAcl=false,checks=checks});
    }
    public sealed class ProcessState {public string environmentId,copyId,operation,boundary;public string[] current;public int pid;}
    public static string Process(string root,string mode,string boundary){
        var json=new JavaScriptSerializer();string statePath=Path.Combine(root,"state.json");
        if(mode=="pause"){
            var c=new Case(root);c.operation="create";bool deleting=boundary.StartsWith("staging-delet",StringComparison.Ordinal)||boundary=="staging-directory-removed";
            if(deleting)c.Prepare("create","create-before-publish");
            var originals=c.Current();c.observe=point=>{if(point!=boundary)return;string snapshots=Path.Combine(c.allocation,"snapshots");
                if(c.copyId==null){string prefix=Directory.GetDirectories(snapshots,"create-next-*").SingleOrDefault();c.copyId=prefix!=null?Path.GetFileName(prefix).Substring("create-next-".Length):Directory.GetDirectories(snapshots).Select(Path.GetFileName).Single(name=>{Guid id;return Guid.TryParseExact(name,"D",out id);});}
                var state=new ProcessState{environmentId=c.id,copyId=c.copyId,operation=c.operation,boundary=boundary,current=originals,pid=System.Diagnostics.Process.GetCurrentProcess().Id};
                using(var output=new FileStream(statePath,FileMode.CreateNew,FileAccess.Write,FileShare.None)){var bytes=Encoding.UTF8.GetBytes(json.Serialize(state));output.Write(bytes,0,bytes.Length);output.Flush(true);}System.IO.File.WriteAllText(Path.Combine(root,"ready.next"),json.Serialize(state));System.IO.File.Move(Path.Combine(root,"ready.next"),Path.Combine(root,"ready.json"));using(var wait=new ManualResetEvent(false))wait.WaitOne(60000);throw new TimeoutException("Fixture producer was not terminated");
            };
            if(deleting){var review=c.Review();c.factory.Cleanup(c.copyId,c.operation,review.token,false,()=>{},CancellationToken.None);}else c.Store().Create("process-copy","opaque-process-configuration",CancellationToken.None);
            throw new InvalidOperationException("Fixture did not reach the requested boundary");
        }
        var previous=json.Deserialize<ProcessState>(System.IO.File.ReadAllText(statePath));Guid parsed;if(!Guid.TryParseExact(previous.environmentId,"D",out parsed)||!Guid.TryParseExact(previous.copyId,"D",out parsed)||previous.boundary!=boundary||previous.operation!="create")throw new IOException("Process fixture identity changed");
        var reopened=new Case(root,previous.environmentId){copyId=previous.copyId,operation=previous.operation};
        if(mode=="live"){
            bool denied=false;try{reopened.Review();}catch(IOException error){denied=error.Message.Contains("(32)");}Require(denied,"Live producer receipt did not hold an OS sharing fence");return json.Serialize(new{complete=true,producerBusy=true,pid=System.Diagnostics.Process.GetCurrentProcess().Id});
        }
        if(mode!="resume")throw new ArgumentException("Process fixture mode");Require(reopened.Current().SequenceEqual(previous.current),"Process death changed current files");
        bool published=boundary=="staging-directory-published";
        if(published){Require(Fails(()=>reopened.Review()),"Published copy offered for cleanup");Require(reopened.Store().Get(previous.copyId).id==previous.copyId,"Published data lost after process death");}
        else{var review=reopened.Review();reopened.Clean(review.phase!="copy");}
        Require(reopened.Current().SequenceEqual(previous.current),"Cleanup changed source files");
        return json.Serialize(new{complete=true,pid=System.Diagnostics.Process.GetCurrentProcess().Id,environmentId=previous.environmentId,copyId=previous.copyId,boundary=boundary,publishedCopyPreserved=published,cleanupComplete=!published,originalFilesUnchanged=true,actualHyperV=false,protectedAcl=false});
    }
